insert into prep.summaries (id, grp, free, sort, data) values
  ('a3-admin', 'A3', false, 0, '{"id":"a3-admin","group":"A3","topics":["A3-ADMIN"],"icon":"🏛️","title":"พ.ร.บ.ระเบียบบริหารราชการแผ่นดิน พ.ศ. 2534","hub":"บริหารราชการแผ่นดิน","hubSub":"พ.ศ. 2534 · แก้ไขหลายฉบับ","branches":[{"id":"parts","icon":"🧩","tone":"pink","title":"แบ่งการบริหาร","big":"3","unit":"ส่วน","must":true,"sub":"ส่วนกลาง · ส่วนภูมิภาค · ส่วนท้องถิ่น","ask":"บริหารราชการแผ่นดินแบ่งเป็นกี่ส่วน","blocks":[{"k":"table","head":["ส่วน","ประกอบด้วย"],"rows":[["ส่วนกลาง","สำนักนายกรัฐมนตรี กระทรวง ทบวง กรม"],["ส่วนภูมิภาค","จังหวัด อำเภอ"],["ส่วนท้องถิ่น","อบจ. เทศบาล อบต. กรุงเทพมหานคร เมืองพัทยา"]]},{"k":"memo","t":"\"กลาง-ภูมิ-ถิ่น\" มีผู้ว่าฯ = ภูมิภาค · มีนายก อบจ./นายกเทศมนตรี = ท้องถิ่น"},{"k":"oops","t":"จังหวัด เป็นส่วนภูมิภาค แต่ \"องค์การบริหารส่วนจังหวัด (อบจ.)\" เป็นส่วนท้องถิ่น ชื่อคล้ายกันแต่คนละส่วน"}]},{"id":"central","icon":"🏢","tone":"mint","title":"ส่วนกลาง ใครบังคับบัญชา","big":"เลขาฯ รมต.","ask":"สำนักงานรัฐมนตรี ใครบังคับบัญชา","sub":"สำนักงานรัฐมนตรี = ราชการทางการเมือง","blocks":[{"k":"table","head":["ส่วนราชการ","ผู้บังคับบัญชา"],"rows":[["สำนักนายกรัฐมนตรี (ฐานะเป็นกระทรวง)","นายกรัฐมนตรี"],["สำนักเลขาธิการนายกรัฐมนตรี (การเมือง)","เลขาธิการนายกรัฐมนตรี"],["สำนักงานรัฐมนตรี (การเมือง)","เลขานุการรัฐมนตรี (ข้าราชการการเมือง)"],["สำนักงานปลัดกระทรวง","ปลัดกระทรวง"],["กรม","อธิบดี"]]},{"k":"list","items":[{"icon":"⚖️","t":"สำนักนายกฯ กระทรวง ทบวง กรม มีฐานะเป็นนิติบุคคล"},{"icon":"💻","t":"บริการประชาชนและติดต่อระหว่างส่วนราชการ ต้องใช้แพลตฟอร์มดิจิทัลกลาง","d":"ที่สำนักงานพัฒนารัฐบาลดิจิทัล (องค์การมหาชน) กำหนด"}]}]},{"id":"region","icon":"🗺️","tone":"sky","title":"ส่วนภูมิภาค","big":"จังหวัด","unit":"= นิติบุคคล","ask":"ภูมิภาค หน่วยไหนเป็นนิติบุคคล","sub":"รวมหลายอำเภอเป็นจังหวัด · อำเภอไม่เป็นนิติบุคคล","blocks":[{"k":"pairs","items":[{"a":"จังหวัด","b":"ผู้ว่าราชการจังหวัดเป็นหัวหน้า · เป็นนิติบุคคล"},{"a":"อำเภอ","b":"นายอำเภอเป็นหัวหน้า (สังกัดกระทรวงมหาดไทย) · ไม่เป็นนิติบุคคล"}]},{"k":"list","items":[{"icon":"👥","t":"คณะกรมก