  ('a3-adminproc', 'A3', false, 1, '{"id":"a3-adminproc","group":"A3","topics":["A3-ADMINPROC"],"icon":"📨","title":"พ.ร.บ.วิธีปฏิบัติราชการทางปกครอง พ.ศ. 2539","hub":"วิธีปฏิบัติราชการทางปกครอง","hubSub":"พ.ศ. 2539","branches":[{"id":"order","icon":"📄","tone":"pink","title":"คำสั่งทางปกครอง vs กฎ","big":"เฉพาะราย","must":true,"ask":"คำสั่งทางปกครองมีผลกับใคร","sub":"คำสั่ง = เจาะจงบุคคล · กฎ = ใช้กับทุกคนทั่วไป","blocks":[{"k":"pairs","items":[{"a":"คำสั่งทางปกครอง","b":"มีผลต่อสิทธิหรือหน้าที่ของบุคคลเฉพาะราย เช่น อนุญาตให้ครูลาศึกษาต่อ"},{"a":"กฎ","b":"ใช้บังคับเป็นการทั่วไป ไม่มุ่งบุคคลใด เช่น พ.ร.ฎ. กฎกระทรวง ระเบียบ"}]},{"k":"list","items":[{"icon":"⏰","t":"มีผลตั้งแต่ผู้นั้น \"ได้รับแจ้ง\" เป็นต้นไป","d":"และมีผลจนกว่าจะถูกเพิกถอนหรือสิ้นผล"},{"icon":"🧑‍⚖️","t":"ต้องออกโดยเจ้าหน้าที่ผู้มีอำนาจในเรื่องนั้น"}]}]},{"id":"appeal","icon":"✍️","tone":"mint","title":"อุทธรณ์","big":"15","unit":"วัน","must":true,"ask":"อุทธรณ์คำสั่งทางปกครองภายในกี่วัน","sub":"ทำเป็นหนังสือ ยื่นต่อเจ้าหน้าที่ผู้ออกคำสั่ง","blocks":[{"k":"steps","items":[{"t":"คู่กรณีอุทธรณ์ภายใน 15 วัน","d":"ทำเป็นหนังสือ ระบุข้อโต้แย้ง ข้อเท็จจริง ข้อกฎหมาย"},{"t":"เจ้าหน้าที่ผู้ออกคำสั่งพิจารณาภายใน 30 วัน","d":"ถ้าไม่เห็นด้วย ต้องรายงานผู้มีอำนาจพิจารณาอุทธรณ์"},{"t":"ผู้มีอำนาจพิจารณาให้เสร็จภายใน 30 วัน","d":"ขยายได้อีกไม่เกิน 30 วัน"}]},{"k":"memo","t":"\"15 ยื่น · 30 ตรวจ · 30 ชี้ขาด\""}]},{"id":"notice","icon":"📬","tone":"sky","title":"การแจ้ง & นับเวลา","big":"7","unit":"วัน","hot":true,"ask":"ไปรษณีย์ตอบรับในประเทศ ถือว่าได้รับแจ้งเมื่อครบกี่วัน","sub":"ไปรษณีย์ตอบรับในประเทศ ถือว่าได้รับเมื่อครบ 7 วัน","blocks":[{"k":"table","head":["วิธีแจ้ง","ถือว่าได้รับแจ้งเมื่อ"],"rows":[["ส่งหนังสือถึงภูมิลำเนา","ขณะที่หนังสือไปถึง"],["ไปรษณีย์ตอบรับ ในประเทศ","ครบ 7 วันนับแต่วันส่ง"],["ไปรษณีย์ตอบรับ ต่างประเทศ","ครบ 15 วันนับแต่วันส่ง"],["ผู้รับเกิน 50 คน ปิดประกาศ","พ้น 15 วัน"]]},{"k":"pairs","items":[{"a":"เจ้าหน้าที่ต้องทำ","b":"นับวันสุดท้ายด้วย แม้เป็นวันหยุด"},{"a":"บุคคลต้องทำ","b":"ถ้าวันสุ