  ('a1-series', 'A1', false, 6, '{"id":"a1-series","group":"A1","topics":["A1-QUANT-SERIES"],"icon":"🔢","title":"อนุกรม","hub":"อนุกรม","hubSub":"หาผลต่างก่อนเสมอ","intro":"เจอโจทย์อนุกรม ให้ลองตามลำดับกิ่ง 1 → 6","branches":[{"id":"add","icon":"➕","tone":"pink","title":"1. ผลต่างคงที่","big":"+ เท่ากัน","must":true,"ask":"ขั้นแรกของอนุกรมทุกข้อ คือหาอะไร","sub":"ลบตัวหน้าออกจากตัวหลัง ถ้าเท่ากันทุกคู่ จบ","blocks":[{"k":"example","q":"3, 7, 11, 15, ?","steps":["ผลต่าง 4, 4, 4","15 + 4 = 19"],"a":"19"},{"k":"memo","t":"เขียนผลต่างไว้ใต้ตัวเลขทุกครั้ง แค่นี้ก็ตอบได้ครึ่งหนึ่งของข้อสอบ"}]},{"id":"mul","icon":"✖️","tone":"mint","title":"2. คูณหรือหารเท่ากัน","big":"× เท่ากัน","ask":"ผลต่างโตเร็วมาก ให้ลองอะไร","sub":"ตัวเลขโตเร็วมาก ลองหารตัวหลังด้วยตัวหน้า","blocks":[{"k":"example","q":"2, 6, 18, 54, ?","steps":["6÷2 = 3, 18÷6 = 3, 54÷18 = 3","54 × 3 = 162"],"a":"162"},{"k":"note","t":"บางข้อเป็น ×2 +1, ×2 +2 ... ถ้าคูณไม่ลงตัวพอดี ลองคูณแล้วบวกต่อ"}]},{"id":"diff2","icon":"🪜","tone":"sky","title":"3. ผลต่าง 2 ชั้น","big":"ต่างของต่าง","hot":true,"ask":"ผลต่างชั้นแรกไม่เท่ากัน ทำอย่างไรต่อ","sub":"ผลต่างชั้นแรกไม่เท่า ให้หาผลต่างของผลต่างอีกที","blocks":[{"k":"example","q":"2, 5, 10, 17, 26, ?","steps":["ผลต่างชั้นแรก 3, 5, 7, 9","ผลต่างชั้นสอง 2, 2, 2","ผลต่างถัดไป 11 → 26 + 11 = 37"],"a":"37"}]},{"id":"alt","icon":"🔀","tone":"lem","title":"4. สลับสองชุด","big":"คี่ / คู่","ask":"ตัวเลขขึ้น ๆ ลง ๆ ให้แยกตำแหน่งแบบไหน","sub":"ตัวเลขขึ้น ๆ ลง ๆ แยกตำแหน่งคี่กับคู่","blocks":[{"k":"example","q":"1, 10, 3, 20, 5, 30, ?","steps":["ตำแหน่งคี่: 1, 3, 5 (+2)","ตำแหน่งคู่: 10, 20, 30 (+10)","ตัวถัดไปเป็นตำแหน่งคี่ = 7"],"a":"7"}]},{"id":"special","icon":"⭐","tone":"lil","title":"5. ตัวเลขพิเศษ","big":"n² · n³","ask":"ไม่เข้ากิ่ง 1–4 ให้นึกถึงตัวเลขชุดไหน","sub":"กำลังสอง กำลังสาม ฟีโบนัชชี จำนวนเฉพาะ","blocks":[{"k":"table","head":["ชุด","ตัวเลข"],"rows":[["กำลังสอง","1, 4, 9, 16, 25, 36, 49"],["กำลังสาม","1, 8, 27, 64, 125"],["ฟีโบนัชชี (บวกสองตัวหน้า)","1, 1, 2, 3, 5, 8, 13, 21"],["จำนวนเฉพาะ","2, 3, 5, 7, 11, 13, 17, 19"]]},{"k":"memo","t":"ท่องกำลังสองถึง 20² และกำลังสามถึง 10³ ไว้ จะเห็นแพทเทิร์นเร็วขึ้นมาก"}]},{"id":"letters","icon":"🔤","tone":"pea","title":"6. อนุกรมตัวอักษร","big":"A = 1","ask":"อนุกรมตัวอักษร เปลี่ยนเป็นอะไรก่อน","sub":"แปลงเป็นตัวเลขตามลำดับ แล้วทำเหมือนอนุกรมเลข","blocks":[{"k":"example","q":"A, C, F, J, O, ?","steps":["แปลงเป็นเลข 1, 3, 6, 10, 15","ผลต่าง +2, +3, +4, +5 → ถัดไป +6","15 + 6 = 21 = U"],"a":"U"},{"k":"memo","t":"จำจุดหมุด E = 5, J = 10, O = 15, T = 20, Y = 25"}]}]}'::jsonb),
  ('a1-percent', 'A1', false, 7, '{"id":"a1-percent","group":"A1","topics":["A1-QUANT-PERCENT"],"icon":"💯","title":"ร้อยละ (เปอร์เซ็นต์)","hub":"ร้อยละ","hubSub":"ส่วน ÷ ทั้งหมด × 100","branches":[{"id":"basic","icon":"🧮","tone":"pink","title":"หลักคิด","big":"ส่วน ÷ ทั้งหมด","unit":"× 100","must":true,"ask":"หาร้อยละ ใช้สูตรอะไร","blocks":[{"k":"formula","f":"ร้อยละ = ส่วน ÷ ทั้งหมด × 100","d":"หาทั้งหมด = ส่วน ÷ ร้อยละ × 100"},{"k":"example","q":"15 เป็นร้อยละเท่าไรของ 60","steps":["15 ÷ 60 = 0.25","0.25 × 100 = 25"],"a":"ร้อยละ 25"},{"k":"example","q":"ร้อยละ 30 ของจำนวนหนึ่งเท่ากับ 45 จำนวนนั้นคือ","steps":["45 ÷ 30 × 100","= 150"],"a":"150"}]},{"id":"updown","icon":"🎢","tone":"mint","title":"ขึ้นแล้วลง","big":"ลด 4%","hot":true,"ask":"ขึ้นราคา 20% แล้วลด 20% สุดท้ายเป็นอย่างไร","sub":"ขึ้น 20% แล้วลด 20% ไม่กลับเท่าเดิม","blocks":[{"k":"example","q":"สินค้าราคา 100 บาท ขึ้นราคา 20% แล้วลดราคา 20% ราคาสุดท้ายเทียบกับเดิมเป็นอย่างไร","steps":["100 + 20% = 120","120 − 20% = 96","96 เทียบกับ 100 = ลดลง 4%"],"a":"ลดลงร้อยละ 4"},{"k":"memo","t":"ขึ้น a% ลง a% = ลดลง a²/100 % เสมอ (20 → 4, 10 → 1, 30 → 9)"}]},{"id":"stack","icon":"🏷️","tone":"sky","title":"ลดราคาซ้อน","big":"≠ บวกกัน","hot":true,"ask":"ลด 20% แล้วลดอีก 10% รวมลดกี่ %","sub":"ลด 20% แล้วลดอีก 10% = ลด 28% ไม่ใช่ 30%","blocks":[{"k":"formula","f":"เหลือ = (1 − a) × (1 − b)","d":"ลดรวม = 1 − (0.8 × 0.9) = 0.28 = 28%"},{"k":"example","q":"ราคาหลังลด 25% เหลือ 600 บาท ราคาป้ายคือ","steps":["600 = ราคาป้าย × 0.75","ราคาป้าย = 600 ÷ 0.75 = 800"],"a":"800 บาท"}]},{"id":"profit","icon":"📈","tone":"lem","title":"กำไร-ขาดทุน","big":"คิดจากทุน","must":true,"ask":"ร้อยละกำไร คิดเทียบกับอะไร","sub":"ร้อยละกำไร = กำไร ÷ ทุน × 100","blocks":[{"k":"example","q":"ซื้อมา 400 บาท ขายไป 500 บาท ได้กำไรร้อยละเท่าไร","steps":["กำไร = 500 − 400 = 100","100 ÷ 400 × 100 = 25"],"a":"ร้อยละ 25"},{"k":"oops","t":"อย่าหารด้วยราคาขาย ถ้าโจทย์ไม่ได้บอกเป็นอย่างอื่น ร้อยละกำไรคิดจากทุนเสมอ"}]},{"id":"interest","icon":"🏦","tone":"lil","title":"ดอกเบี้ยเชิงเดียว","big":"ต้น × อัตรา × ปี","ask":"สูตรดอกเบี้ยเชิงเดียว","blocks":[{"k":"example","q":"ฝากเงิน 10,000 บาท ดอกเบี้ย 5% ต่อปี 3 ปี (เชิงเดียว) ได้ดอกเบี้ยเท่าไร","steps":["10,000 × 0.05 = 500 ต่อปี","500 × 3 = 1,500"],"a":"1,500 บาท"}]},{"id":"change","icon":"↕️","tone":"pea","title":"เปลี่ยนแปลงกี่ %","big":"เทียบตัวเก่า","ask":"ร้อยละการเปลี่ยนแปลง หารด้วยค่าไหน","sub":"(ใหม่ − เก่า) ÷ เก่า × 100","blocks":[{"k":"pairs","items":[{"a":"80 → 100","b":"เพิ่มขึ้น 20 ÷ 80 = 25%"},{"a":"100 → 80","b":"ลดลง 20 ÷ 100 = 20%"}]},{"k":"memo","t":"ต่างกัน 20 เท่ากัน แต่ร้อยละไม่เท่ากัน เพราะ \"ฐาน\" คือค่าเก่า"}]}]}'::jsonb),
  ('a1-ratio', 'A1', false, 8, '{"id":"a1-ratio","group":"A1","topics":["A1-QUANT-RATIO"],"icon":"⚖️","title":"อัตราส่วนและสัดส่วน","hub":"อัตราส่วน","hubSub":"แบ่ง · เทียบ · ผสม","branches":[{"id":"link","icon":"🔗","tone":"pink","title":"เชื่อมสองอัตราส่วน","big":"ทำตัวกลางให้เท่า","must":true,"ask":"A:B กับ B:C รวมเป็น A:B:C ต้องทำอะไร","blocks":[{"k":"example","q":"A : B = 2 : 3 และ B : C = 4 : 5 จงหา A : B : C","steps":["ทำ B ให้เท่ากัน: ค.ร.น. ของ 3 กับ 4 = 12","A : B = 8 : 12 และ B : C = 12 : 15"],"a":"8 : 12 : 15"}]},{"id":"share","icon":"🍰","tone":"mint","title":"แบ่งตามอัตราส่วน","big":"รวมส่วนก่อน","ask":"แบ่งเงินตามอัตราส่วน ขั้นแรกทำอะไร","blocks":[{"k":"example","q":"แบ่งเงิน 1,200 บาท ให้ 3 คนในอัตราส่วน 1 : 2 : 3","steps":["รวมส่วน 1 + 2 + 3 = 6","ส่วนละ 1,200 ÷ 6 = 200"],"a":"200, 400, 600 บาท"}]},{"id":"inverse","icon":"👷","tone":"sky","title":"แปรผกผัน","big":"คนมาก วันน้อย","hot":true,"ask":"คนงานเพิ่มขึ้น จำนวนวันเป็นอย่างไร","sub":"คน × วัน = งาน (คงที่)","blocks":[{"k":"example","q":"คนงาน 6 คน ทำงานเสร็จใน 10 วัน ถ้าเหลือ 4 คน จะเสร็จในกี่วัน","steps":["งานทั้งหมด = 6 × 10 = 60 คน-วัน","60 ÷ 4 = 15"],"a":"15 วัน"},{"k":"oops","t":"คนน้อยลง วันต้องมากขึ้น ถ้าคำตอบได้น้อยกว่าเดิม แปลว่าคิดเป็นแปรผันตรงผิดทาง"}]},{"id":"age","icon":"🎂","tone":"lem","title":"โจทย์อายุ","big":"ทุกคนแก่เท่ากัน","ask":"ผ่านไป n ปี อายุของแต่ละคนเพิ่มเท่าไร","sub":"อีก n ปี ทุกคน + n ปีเท่ากัน","blocks":[{"k":"example","q":"พ่ออายุเป็น 3 เท่าของลูก อีก 10 ปี พ่อจะอายุเป็น 2 เท่าของลูก ตอนนี้ลูกอายุเท่าไร","steps":["ให้ลูก = x พ่อ = 3x","3x + 10 = 2(x + 10)","3x + 10 = 2x + 20 → x = 10"],"a":"ลูก 10 ปี (พ่อ 30 ปี)"}]},{"id":"mix","icon":"🧪","tone":"lil","title":"ผสมสาร / เจือจาง","big":"เนื้อสารคงที่","ask":"เติมน้ำลงในสารละลาย อะไรไม่เปลี่ยน","sub":"เติมน้ำ ปริมาณเนื้อสารไม่เปลี่ยน","blocks":[{"k":"example","q":"น้ำเชื่อมเข้มข้น 20% หนัก 300 กรัม ต้องเติมน้ำอีกกี่กรัม ให้เหลือเข้มข้น 15%","steps":["น้ำตาล = 20% × 300 = 60 กรัม","60 กรัม ต้องเป็น 15% ของทั้งหมด → 60 ÷ 0.15 = 400","เติมน้ำ 400 − 300 = 100"],"a":"100 กรัม"}]}]}'::jsonb),
  ('a1-word', 'A1', true, 9, '{"id":"a1-word","group":"A1","topics":["A1-QUANT-WORD"],"icon":"🧠","free":true,"title":"โจทย์ปัญหายอดฮิต 1","hub":"โจทย์ยอดฮิต","hubSub":"เสาไฟ · ขาสัตว์ · ความเร็ว","branches":[{"id":"poles","icon":"💡","tone":"pink","title":"นับเสาไฟ / ต้นไม้","big":"ช่วง + 1","must":true,"hot":true,"ask":"ปักเสาเป็นแนวตรง ปักหัวท้าย จำนวนต้น = ?","sub":"แนวตรง ปักทั้งสองปลาย = ระยะ ÷ ช่วง + 1","blocks":[{"k":"table","head":["แบบ","จำนวนต้น"],"rows":[["แนวตรง ปักทั้งสองปลาย","ระยะ ÷ ช่วง + 1"],["แนวตรง ปักปลายเดียว","ระยะ ÷ ช่วง"],["แนวตรง ไม่ปักปลายเลย","ระยะ ÷ ช่วง − 1"],["วงกลม / รอบสระ","ระยะรอบ ÷ ช่วง"]]},{"k":"example","q":"ถนนยาว 100 เมตร ปักเสาไฟทุก 10 เมตร ทั้งสองข้างทาง โดยปักที่ต้นและปลายถนนด้วย ใช้เสากี่ต้น","steps":["ข้างเดียว = 100 ÷ 10 + 1 = 11","สองข้างทาง × 2 = 22"],"a":"22 ต้น"},{"k":"oops","t":"อย่าลืมดูคำว่า \"สองข้างทาง\" และ \"รอบสระ\" สองคำนี้ทำให้คำตอบเปลี่ยน"}]},{"id":"legs","icon":"🐔","tone":"mint","title":"นับขาสัตว์","big":"สมมติเป็นไก่หมด","must":true,"hot":true,"ask":"โจทย์ไก่กับหมู เริ่มจากสมมติอะไร","sub":"ขาที่เกินมา ÷ ขาที่ต่างกัน = จำนวนสัตว์ 4 ขา","blocks":[{"k":"example","q":"ไก่กับหมูรวมกัน 20 ตัว นับขาได้ 56 ขา มีหมูกี่ตัว","steps":["สมมติเป็นไก่ทั้งหมด: 20 × 2 = 40 ขา","ขาที่เกินมา 56 − 40 = 16 ขา","หมูมีขามากกว่าไก่ตัวละ 2 → 16 ÷ 2 = 8"],"a":"หมู 8 ตัว (ไก่ 12 ตัว)"},{"k":"memo","t":"ตรวจคำตอบ: 12 × 2 + 8 × 4 = 24 + 32 = 56 ✓"}]},{"id":"speed","icon":"🚗","tone":"sky","title":"ความเร็ว-ระยะ-เวลา","big":"ระยะ = เร็ว × เวลา","ask":"สูตรหลักของโจทย์ความเร็ว","sub":"สวนกันให้บวกความเร็ว · ไล่กันให้ลบ","blocks":[{"k":"pairs","items":[{"a":"วิ่งสวนกัน","b":"เวลาที่พบกัน = ระยะห่าง ÷ (v₁ + v₂)"},{"a":"วิ่งไล่กัน","b":"เวลาที่ไล่ทัน = ระยะห่าง ÷ (v₁ − v₂)"}]},{"k":"example","q":"รถ A เร็ว 60 กม./ชม. รถ B เร็ว 40 กม./ชม. อยู่ห่างกัน 200 กม. วิ่งเข้าหากัน จะพบกันในกี่ชั่วโมง","steps":["สวนกัน บวกความเร็ว 60 + 40 = 100","200 ÷ 100 = 2"],"a":"2 ชั่วโมง"},{"k":"formula","f":"ไป a กลับ b ความเร็วเฉลี่ย = 2ab ÷ (a + b)","d":"ไป 60 กลับ 40 → 2×60×40 ÷ 100 = 48 ไม่ใช่ 50"}]},{"id":"work","icon":"🛠️","tone":"lem","title":"ทำงานร่วม / ท่อน้ำ","big":"ab ÷ (a+b)","ask":"สองคนทำงานร่วมกัน ใช้สูตรอะไร","sub":"A ทำ a วัน B ทำ b วัน ช่วยกัน = ab ÷ (a + b)","blocks":[{"k":"example","q":"A ทำงานเสร็จใน 6 วัน B ทำเสร็จใน 3 วัน ช่วยกันทำจะเสร็จในกี่วัน","steps":["ต่อวัน A ทำได้ 1/6 B ทำได้ 1/3","รวม 1/6 + 1/3 = 1/2 ต่อวัน","หรือใช้สูตร 6×3 ÷ (6+3) = 2"],"a":"2 วัน"},{"k":"example","q":"ท่อเติมน้ำเต็มถังใน 4 ชม. ท่อปล่อยน้ำหมดถังใน 6 ชม. เปิดพร้อมกัน ถังจะเต็มในกี่ชั่วโมง","steps":["ต่อชั่วโมง 1/4 − 1/6 = 1/12","เต็มถังใน 12 ชั่วโมง"],"a":"12 ชั่วโมง"}]},{"id":"match","icon":"🏅","tone":"lil","title":"จับมือ / แข่งขัน","big":"n(n−1) ÷ 2","ask":"n คนจับมือกันครบทุกคน กี่ครั้ง","sub":"จับมือครบทุกคน = แข่งแบบพบกันหมด","blocks":[{"k":"pairs","items":[{"a":"พบกันหมด / จับมือ","b":"n(n − 1) ÷ 2 เช่น 10 คน = 45 ครั้ง, 6 ทีม = 15 นัด"},{"a":"แพ้คัดออก","b":"n − 1 นัด เช่น 16 ทีม = 15 นัด"}]}]},{"id":"queue","icon":"🚶","tone":"pea","title":"ต่อแถว","big":"หน้า + หลัง − 1","ask":"เป็นคนที่ 7 จากหน้า และที่ 5 จากหลัง มีกี่คน","sub":"นับตัวเองซ้ำ ต้องลบออก 1","blocks":[{"k":"example","q":"แดงยืนเป็นคนที่ 7 นับจากหัวแถว และเป็นคนที่ 5 นับจากท้ายแถว แถวนี้มีกี่คน","steps":["7 + 5 = 12 (นับแดงซ้ำ 2 ครั้ง)","12 − 1 = 11"],"a":"11 คน"}]}]}'::jsonb),
  ('a1-word2', 'A1', false, 10, '{"id":"a1-word2","group":"A1","topics":["A1-QUANT-WORD"],"icon":"🕐","title":"โจทย์ปัญหายอดฮิต 2","hub":"โจทย์ยอดฮิต 2","hubSub":"วัน · นาฬิกา · ค.ร.น.","branches":[{"id":"days","icon":"📅","tone":"pink","title":"วันในสัปดาห์","big":"หารด้วย 7","must":true,"ask":"อีก 100 วันเป็นวันอะไร ต้องหารด้วยเลขอะไร","sub":"ดูแค่เศษ แล้วนับต่อจากวันนี้","blocks":[{"k":"example","q":"วันนี้วันจันทร์ อีก 100 วันจะเป็นวันอะไร","steps":["100 ÷ 7 = 14 เศษ 2","นับต่อจากวันจันทร์ไป 2 วัน"],"a":"วันพุธ"}]},{"id":"clock","icon":"🕒","tone":"mint","title":"มุมเข็มนาฬิกา","big":"|30H − 5.5M|","ask":"สูตรมุมระหว่างเข็มนาฬิกา","sub":"H = ชั่วโมง M = นาที","blocks":[{"k":"example","q":"เวลา 3:30 น. เข็มยาวกับเข็มสั้นทำมุมกันกี่องศา","steps":["30 × 3 = 90","5.5 × 30 = 165","|90 − 165| = 75"],"a":"75 องศา"},{"k":"note","t":"ถ้าได้เกิน 180 องศา ให้เอา 360 ลบ"}]},{"id":"avg","icon":"📊","tone":"sky","title":"ค่าเฉลี่ย","big":"เฉลี่ย × จำนวน","unit":"= ผลรวม","hot":true,"ask":"รู้ค่าเฉลี่ยกับจำนวน หาอะไรได้","blocks":[{"k":"example","q":"สอบ 4 ครั้งได้คะแนนเฉลี่ย 70 ครั้งที่ 5 ต้องได้เท่าไร คะแนนเฉลี่ยทั้ง 5 ครั้งจึงเป็น 72","steps":["ผลรวมที่ต้องการ 72 × 5 = 360","ผลรวม 4 ครั้งแรก 70 × 4 = 280","360 − 280 = 80"],"a":"80 คะแนน"}]},{"id":"lcm","icon":"🔔","tone":"lem","title":"ค.ร.น. / ห.ร.ม.","big":"พร้อมกัน = ค.ร.น.","ask":"\"เกิดพร้อมกันอีกครั้ง\" ใช้ ค.ร.น. หรือ ห.ร.ม.","sub":"เกิดพร้อมกันอีกครั้ง = ค.ร.น. · ตัดยาวเท่ากันยาวที่สุด = ห.ร.ม.","blocks":[{"k":"example","q":"ไฟ A กะพริบทุก 6 วินาที ไฟ B กะพริบทุก 8 วินาที เพิ่งกะพริบพร้อมกัน อีกกี่วินาทีจะกะพริบพร้อมกันอีก","steps":["ค.ร.น. ของ 6 และ 8 = 24"],"a":"24 วินาที"},{"k":"example","q":"เชือก 24 เมตร และ 36 เมตร ตัดเป็นท่อนยาวเท่ากันและยาวที่สุด ท่อนละกี่เมตร","steps":["ห.ร.ม. ของ 24 และ 36 = 12"],"a":"12 เมตร"}]},{"id":"pages","icon":"📖","tone":"lil","title":"พิมพ์เลขหน้า","big":"192","unit":"ตัว","ask":"พิมพ์เลขหน้า 1–100 ใช้ตัวเลขกี่ตัว","sub":"พิมพ์เลขหน้า 1–100 ใช้ตัวเลข 192 ตัว","blocks":[{"k":"table","head":["ช่วงหน้า","ตัวเลขที่ใช้"],"rows":[["1–9","9 × 1 = 9"],["10–99","90 × 2 = 180"],["100","3"],["รวม","192"]]}]},{"id":"sum","icon":"➕","tone":"pea","title":"ผลบวกเลขเรียง","big":"n(n+1) ÷ 2","ask":"1 + 2 + ... + n เท่ากับ","sub":"1 + 2 + ... + 100 = 5,050","blocks":[{"k":"formula","f":"1 + 2 + 3 + ... + n = n(n + 1) ÷ 2","d":"1 ถึง 100 = 100 × 101 ÷ 2 = 5,050"},{"k":"formula","f":"เลขคี่ n ตัวแรก รวมกัน = n²","d":"1 + 3 + 5 + 7 + 9 = 25 = 5²"}]}]}'::jsonb),
  ('a1-data', 'A1', false, 11, '{"id":"a1-data","group":"A1","topics":["A1-QUANT-DATA"],"icon":"📊","title":"ตาราง กราฟ และข้อมูล","hub":"อ่านข้อมูล","hubSub":"ดูหน่วยก่อนทุกครั้ง","branches":[{"id":"unit","icon":"🔎","tone":"pink","title":"ดูหน่วยก่อน","big":"พัน · ล้าน","must":true,"ask":"ก่อนคำนวณจากตาราง ต้องดูอะไรก่อน","sub":"ตารางหน่วย \"พันคน\" ตัวเลข 12 = 12,000 คน","blocks":[{"k":"list","items":[{"icon":"1️⃣","t":"อ่านชื่อตาราง หัวคอลัมน์ และหน่วย"},{"icon":"2️⃣","t":"อ่านคำถามว่าถาม \"จำนวน\" หรือ \"ร้อยละ\""},{"icon":"3️⃣","t":"ปัดเลขประมาณก่อน แล้วตัดตัวเลือกที่ไกลเกินไป"}]}]},{"id":"change","icon":"📈","tone":"mint","title":"ร้อยละที่เปลี่ยน","big":"÷ ค่าเก่า","hot":true,"ask":"ร้อยละการเพิ่มขึ้น หารด้วยค่าปีไหน","blocks":[{"k":"formula","f":"(ค่าใหม่ − ค่าเก่า) ÷ ค่าเก่า × 100"},{"k":"pairs","items":[{"a":"80 → 100","b":"เพิ่มขึ้น 25%"},{"a":"100 → 80","b":"ลดลง 20%"}]},{"k":"oops","t":"\"เพิ่มขึ้นมากที่สุด\" ต้องดูว่าถามจำนวนที่เพิ่ม หรือร้อยละที่เพิ่ม คำตอบอาจเป็นคนละแถว"}]},{"id":"pie","icon":"🥧","tone":"sky","title":"แผนภูมิวงกลม","big":"1% = 3.6°","ask":"ร้อยละ 1 ในแผนภูมิวงกลม เท่ากับกี่องศา","sub":"25% = 90° · 50% = 180°","blocks":[{"k":"formula","f":"องศา = ร้อยละ × 3.6","d":"ร้อยละ = องศา ÷ 3.6"},{"k":"example","q":"แผนภูมิวงกลมงบประมาณ 2,000,000 บาท ส่วนของกีฬาทำมุม 72° ได้งบเท่าไร","steps":["72 ÷ 360 = 1/5","2,000,000 ÷ 5 = 400,000"],"a":"400,000 บาท"}]},{"id":"center","icon":"🎯","tone":"lem","title":"ค่ากลาง","big":"เฉลี่ย มัธยฐาน ฐานนิยม","ask":"ค่ากลาง 3 แบบ มีอะไรบ้าง","blocks":[{"k":"example","q":"ข้อมูล 3, 5, 5, 7, 10","steps":["ค่าเฉลี่ย = 30 ÷ 5 = 6","มัธยฐาน (ตัวกลางเมื่อเรียงแล้ว) = 5","ฐานนิยม (ซ้ำมากสุด) = 5"],"a":"6, 5, 5"},{"k":"note","t":"ข้อมูลจำนวนคู่ มัธยฐาน = ค่าเฉลี่ยของสองตัวกลาง"}]},{"id":"ratio","icon":"🧩","tone":"lil","title":"สัดส่วนจากตาราง","big":"ส่วน ÷ รวม","ask":"หาสัดส่วนของกลุ่มหนึ่งจากตาราง","blocks":[{"k":"example","q":"โรงเรียนมีนักเรียนชาย 240 คน หญิง 360 คน นักเรียนชายคิดเป็นร้อยละเท่าไร","steps":["รวม 240 + 360 = 600","240 ÷ 600 × 100 = 40"],"a":"ร้อยละ 40"}]}]}'::jsonb),
  ('a1-cond', 'A1', false, 12, '{"id":"a1-cond","group":"A1","topics":["A1-LOGIC-COND"],"icon":"🔣","title":"เงื่อนไขสัญลักษณ์และเงื่อนไขภาษา","hub":"เงื่อนไข","hubSub":"ต่อโซ่ทิศเดียวกัน","branches":[{"id":"chain","icon":"⛓️","tone":"pink","title":"ต่อโซ่ทิศเดียวกัน","big":"> > ได้ >","must":true,"ask":"A > B และ B > C สรุปได้ไหม","sub":"A > B และ B > C จึงสรุปได้ว่า A > C","blocks":[{"k":"table","head":["ผสมกัน","ผล"],"rows":[[">  กับ  >",">"],[">  กับ  ≥",">"],["≥  กับ  ≥","≥"],["=  กับ  อะไรก็ได้","ใช้เครื่องหมายอีกตัว"]]},{"k":"memo","t":"\"มีมากกว่าแท้ (>) อยู่ตัวเดียว ก็ได้ > ทั้งโซ่\""}]},{"id":"cant","icon":"🚧","tone":"mint","title":"ทิศสวนกัน","big":"สรุปไม่ได้","hot":true,"ask":"A > B และ C > B สรุป A กับ C ได้ไหม","sub":"A > B < C → A กับ C ไม่แน่นอน","blocks":[{"k":"pairs","items":[{"a":"A > B > C","b":"สรุป A > C ได้"},{"a":"A > B < C","b":"สรุปความสัมพันธ์ A กับ C ไม่ได้"}]},{"k":"oops","t":"เจอเครื่องหมายหันคนละทางระหว่างสองตัวที่ถาม ตอบ \"ไม่แน่ชัด\" ทันที"}]},{"id":"example","icon":"📝","tone":"sky","title":"ตัวอย่างโจทย์จริง","big":"อ่านทีละคู่","ask":"ตรวจข้อสรุปทีละข้อ ต้องดูเส้นทางระหว่างตัวไหน","blocks":[{"k":"example","q":"กำหนด A > B ≥ C = D < E\nข้อสรุป 1: A > D\nข้อสรุป 2: B > E","steps":["ข้อ 1: A > B ≥ C = D ทิศเดียวกันตลอด → A > D ถูก","ข้อ 2: B ≥ C = D < E มีทิศสวน → สรุปไม่ได้"],"a":"ข้อ 1 ถูก ข้อ 2 ไม่แน่ชัด"}]},{"id":"or","icon":"🔀","tone":"lem","title":"≥ แปลว่า","big":"> หรือ =","ask":"A ≥ B แปลว่าอะไร","blocks":[{"k":"note","t":"A ≥ B คือ A > B หรือ A = B อย่างใดอย่างหนึ่ง จึงสรุปว่า A > B แน่นอนไม่ได้"}]},{"id":"seat","icon":"🪑","tone":"lil","title":"เงื่อนไขภาษา / จัดที่นั่ง","big":"วาดช่องก่อน","ask":"โจทย์จัดลำดับหรือที่นั่ง เริ่มอย่างไร","sub":"ใส่เงื่อนไขที่แน่นอนก่อน แล้วค่อยเติมที่เหลือ","blocks":[{"k":"steps","items":[{"t":"วาดช่องตามจำนวนคนหรือที่นั่ง"},{"t":"ใส่ข้อมูลที่ระบุตำแหน่งแน่นอนก่อน","d":"เช่น \"ก นั่งริมซ้ายสุด\""},{"t":"ใส่เงื่อนไขติดกัน / ห่างกัน แล้วตัดกรณีที่ขัดแย้ง"},{"t":"เหลือหลายกรณี ให้ดูว่าคำถามต้องการสิ่งที่ \"จริงแน่นอน\" หรือ \"อาจจะจริง\""}]}]}]}'::jsonb),
  ('a1-syllogism', 'A1', false, 13, '{"id":"a1-syllogism","group":"A1","topics":["A1-LOGIC-SYLLOGISM"],"icon":"⭕","title":"การสรุปความเชิงตรรกะ","hub":"สรุปความ","hubSub":"วาดวงกลมเวนน์","branches":[{"id":"all","icon":"🎯","tone":"pink","title":"ทุก A เป็น B","big":"A อยู่ใน B","must":true,"ask":"\"ทุก A เป็น B\" วาดวงกลมแบบไหน","sub":"วง A อยู่ข้างในวง B","blocks":[{"k":"oops","t":"\"ทุกครูเป็นข้าราชการ\" ไม่ได้แปลว่า \"ทุกข้าราชการเป็นครู\" กลับด้านไม่ได้"}]},{"id":"some","icon":"🫧","tone":"mint","title":"บาง A เป็น B","big":"วงซ้อนกัน","ask":"\"บาง A เป็น B\" วาดวงกลมแบบไหน","sub":"วง A กับวง B ซ้อนกันบางส่วน","blocks":[{"k":"note","t":"\"บาง\" ในตรรกะ แปลว่ามีอย่างน้อยหนึ่ง และอาจเป็นทั้งหมดก็ได้"}]},{"id":"none","icon":"🚫","tone":"sky","title":"ไม่มี A ที่เป็น B","big":"วงแยกกัน","ask":"\"ไม่มี A ที่เป็น B\" วาดวงกลมแบบไหน","sub":"วง A กับวง B ไม่แตะกันเลย","blocks":[{"k":"note","t":"\"ไม่มี A ที่เป็น B\" กลับด้านได้ = \"ไม่มี B ที่เป็น A\""}]},{"id":"rule","icon":"📏","tone":"lem","title":"กฎสรุปไว","big":"บาง + บาง","unit":"= สรุปไม่ได้","hot":true,"ask":"ข้อมูลมี \"บาง\" สองตัว สรุปได้ไหม","blocks":[{"k":"table","head":["ข้อมูล","สรุป"],"rows":[["ทุก + ทุก","ทุก"],["ทุก + ไม่มี","ไม่มี"],["บาง + ทุก (ต่อกันถูกทาง)","บาง"],["บาง + บาง","สรุปไม่ได้"]]},{"k":"example","q":"ครูทุกคนเป็นข้าราชการ ข้าราชการบางคนเป็นนักกีฬา\nสรุปว่า \"ครูบางคนเป็นนักกีฬา\" ได้หรือไม่","steps":["วาดวงครูอยู่ในวงข้าราชการ","วงนักกีฬาซ้อนข้าราชการ ตรงส่วนที่ไม่ใช่ครูก็ได้"],"a":"สรุปแน่นอนไม่ได้"}]},{"id":"ifthen","icon":"➡️","tone":"lil","title":"ถ้า...แล้ว","big":"ไม่ q → ไม่ p","hot":true,"ask":"\"ถ้า p แล้ว q\" สรุปแบบไหนได้แน่นอน","sub":"ถ้า p แล้ว q สรุปได้แค่ ถ้าไม่ q แล้วไม่ p","blocks":[{"k":"table","head":["จาก \"ถ้าฝนตก ถนนเปียก\"","ผล"],"rows":[["ถนนไม่เปียก → ฝนไม่ตก","ถูก"],["ถนนเปียก → ฝนตก","ไม่แน่ (อาจมีคนรดน้ำ)"],["ฝนไม่ตก → ถนนไม่เปียก","ไม่แน่"]]},{"k":"memo","t":"\"กลับข้าง + ใส่ไม่ ทั้งคู่\" ถึงจะยังจริง"}]}]}'::jsonb),
  ('a1-analogy', 'A1', false, 14, '{"id":"a1-analogy","group":"A1","topics":["A1-LOGIC-ANALOGY"],"icon":"🔗","title":"อุปมาอุปไมย","hub":"อุปมาอุปไมย","hubSub":"แต่งประโยคเชื่อมคู่แรก","intro":"แต่งประโยคเชื่อมคู่แรก แล้วเอาประโยคเดียวกันไปลองกับทุกตัวเลือก","branches":[{"id":"func","icon":"✂️","tone":"pink","title":"หน้าที่ / การใช้งาน","big":"มีด : ตัด","must":true,"ask":"ปากกา : เขียน เป็นความสัมพันธ์แบบไหน","sub":"ปากกา : เขียน = มีด : ตัด","blocks":[{"k":"note","t":"ประโยคเชื่อม: \"X ใช้สำหรับ Y\""}]},{"id":"part","icon":"🚗","tone":"mint","title":"ส่วนประกอบ","big":"ล้อ : รถ","ask":"ล้อ : รถยนต์ เป็นความสัมพันธ์แบบไหน","sub":"ล้อ : รถยนต์ = ใบ : ต้นไม้","blocks":[{"k":"note","t":"ประโยคเชื่อม: \"X เป็นส่วนหนึ่งของ Y\""}]},{"id":"tool","icon":"🩺","tone":"sky","title":"ผู้ใช้ - เครื่องมือ","big":"หมอ : หูฟัง","ask":"หมอ : หูฟัง เป็นความสัมพันธ์แบบไหน","sub":"หมอ : หูฟัง = ช่างไม้ : ค้อน","blocks":[{"k":"oops","t":"ดูลำดับให้ดี \"หมอ : หูฟัง\" ไม่เท่ากับ \"ค้อน : ช่างไม้\" เพราะสลับหน้าหลัง"}]},{"id":"degree","icon":"🌡️","tone":"lem","title":"ระดับ / ตรงข้าม","big":"อุ่น : ร้อน","hot":true,"ask":"อุ่น : ร้อน เป็นความสัมพันธ์แบบไหน","sub":"อุ่น : ร้อน = เย็น : หนาว","blocks":[{"k":"pairs","items":[{"a":"ระดับมากขึ้น","b":"อุ่น : ร้อน = เย็น : หนาว · ยิ้ม : หัวเราะ"},{"a":"ตรงข้าม","b":"สูง : ต่ำ = ร้อน : เย็น"}]}]},{"id":"cause","icon":"💥","tone":"lil","title":"เหตุ - ผล / ชนิด - ประเภท","big":"เหตุ → ผล","ask":"ขยัน : สำเร็จ เป็นความสัมพันธ์แบบไหน","sub":"ขยัน : สำเร็จ · กุหลาบ : ดอกไม้","blocks":[{"k":"pairs","items":[{"a":"เหตุ - ผล","b":"ขยัน : สำเร็จ = ประมาท : อุบัติเหตุ"},{"a":"ชนิด - ประเภท","b":"กุหลาบ : ดอกไม้ = ทุเรียน : ผลไม้"}]}]},{"id":"number","icon":"🔢","tone":"pea","title":"อุปมาตัวเลข","big":"2 : 8 = 3 : 27","ask":"2 : 8 = 3 : ?","sub":"ความสัมพันธ์ n : n³","blocks":[{"k":"list","items":[{"icon":"🔍","t":"ลองคูณ หาร ยกกำลัง หรือบวกคงที่ ระหว่างตัวหน้ากับตัวหลัง"},{"icon":"✅","t":"ใช้กฎเดียวกันกับคู่ที่สอง แล้วตรวจกับทุกตัวเลือก"}]}]}]}'::jsonb),
  ('a1-thai', 'A1', false, 15, '{"id":"a1-thai","group":"A1","topics":["A1-LANG-USAGE","A1-LANG-READ"],"icon":"📝","title":"การใช้ภาษาไทยและการอ่านจับใจความ","hub":"ภาษาไทย","hubSub":"สะกด · ลักษณนาม · จับใจความ","branches":[{"id":"spell","icon":"✏️","tone":"pink","title":"คำที่มักเขียนผิด","big":"อนุญาต","must":true,"hot":true,"ask":"\"อนุญาต\" สะกดด้วยตัวอะไรท้ายคำ","sub":"สะกดด้วย ต ไม่ใช่ ติ","blocks":[{"k":"words","items":[{"w":"กะทันหัน","m":"ไม่ใช่ กระทันหัน"},{"w":"กะเพรา","m":"ไม่ใช่ กระเพรา"},{"w":"เกร็ดความรู้","m":"ไม่ใช่ เกล็ด"},{"w":"คำนวณ","m":"ไม่ใช่ คำนวน"},{"w":"ปรากฏ","m":"ไม่ใช่ ปรากฎ"},{"w":"ผาสุก","m":"ไม่ใช่ ผาสุข"},{"w":"พิสดาร","m":"ไม่ใช่ พิศดาร"},{"w":"ลายเซ็น","m":"ไม่ใช่ ลายเซ็นต์"},{"w":"สังเกต","m":"ไม่ใช่ สังเกตุ"},{"w":"อานิสงส์","m":"ไม่ใช่ อานิสงฆ์"},{"w":"ไอศกรีม","m":"ไม่ใช่ ไอศครีม"},{"w":"ศีรษะ","m":"ไม่ใช่ ศรีษะ"}]}]},{"id":"classifier","icon":"🐘","tone":"mint","title":"ลักษณนาม","big":"ช้าง = เชือก","ask":"ลักษณนามของช้าง (ช้างบ้าน)","sub":"ช้างบ้านใช้ เชือก","blocks":[{"k":"table","head":["คำ","ลักษณนาม"],"rows":[["ช้าง (ช้างบ้าน)","เชือก"],["พระสงฆ์","รูป"],["ร่ม ช้อน ฉัตร","คัน"],["ขลุ่ย ปี่","เลา"],["ปากกา พู่กัน","ด้าม"],["จดหมาย","ฉบับ"],["บ้าน","หลัง"]]}]},{"id":"main","icon":"🎯","tone":"sky","title":"ใจความสำคัญ","big":"ต้น หรือ ท้าย","unit":"ย่อหน้า","ask":"ใจความสำคัญมักอยู่ส่วนไหนของย่อหน้า","sub":"ประโยคที่คลุมเนื้อหาทั้งย่อหน้า","blocks":[{"k":"list","items":[{"icon":"🔎","t":"ใจความสำคัญ = ประโยคที่ประโยคอื่นมาขยาย","d":"ลองตัดออก ถ้าย่อหน้าเสียความหมาย ประโยคนั้นคือใจความ"},{"icon":"📍","t":"มักอยู่ต้นย่อหน้า รองลงมาคือท้ายย่อหน้า"},{"icon":"❌","t":"ตัวเลือกที่เป็นรายละเอียดหรือตัวอย่าง มักไม่ใช่ใจความสำคัญ"}]}]},{"id":"order","icon":"🧱","tone":"lem","title":"เรียงประโยค","big":"หาประโยคแรก","ask":"เรียงประโยค เริ่มจากหาอะไร","sub":"ประโยคแรกไม่ขึ้นต้นด้วยคำเชื่อมหรือสรรพนาม","blocks":[{"k":"list","items":[{"icon":"1️⃣","t":"ประโยคที่ขึ้นต้นด้วย แต่ ดังนั้น จึง เขา มัน ไม่ใช่ประโยคแรก"},{"icon":"🔚","t":"ประโยคที่มี ดังนั้น สรุปว่า มักเป็นประโยคท้าย"},{"icon":"🔗","t":"จับคู่ประโยคที่มีคำซ้ำหรือสรรพนามอ้างถึงกัน"}]}]},{"id":"wordy","icon":"🧹","tone":"lil","title":"ประโยคบกพร่อง","big":"ฟุ่มเฟือย · กำกวม","ask":"ประโยคบกพร่องที่ออกบ่อยมีแบบไหน","blocks":[{"k":"pairs","items":[{"a":"ฟุ่มเฟือย","b":"ใช้คำซ้ำความหมาย เช่น \"กลับคืนมาอีกครั้งหนึ่ง\""},{"a":"กำกวม","b":"อ่านได้สองความหมาย เช่น \"ภรรยานายทหารที่ไปราชการ\""}]},{"k":"note","t":"ประโยคแบบภาษาพูดในข้อความทางการ ถือเป็นการใช้ภาษาไม่เหมาะสม"}]}]}'::jsonb),
  ('a2-tense', 'A2', false, 16, '{"id":"a2-tense","group":"A2","topics":["A2-GRAMMAR"],"icon":"⏳","title":"Tense ที่ออกบ่อย","hub":"Tenses","hubSub":"ดูคำบอกเวลาก่อน","intro":"หาคำบอกเวลาในประโยคก่อน (yesterday, since, now ...) แล้วจะรู้ tense ทันที","branches":[{"id":"simple","icon":"🔁","tone":"pink","title":"Present Simple","big":"V1 / V-s","must":true,"ask":"ความจริง นิสัย กิจวัตร ใช้ tense อะไร","sub":"ความจริง นิสัย กิจวัตร","blocks":[{"k":"list","items":[{"icon":"🔑","t":"คำบอกเวลา: always, usually, often, every day, on Mondays"},{"icon":"➕","t":"ประธานเอกพจน์ (he, she, it, ชื่อคนเดียว) เติม s/es","d":"She teaches English every day."}]},{"k":"oops","t":"ประโยคบอกความจริง เช่น The sun rises in the east. ใช้ Present Simple เสมอ"}]},{"id":"cont","icon":"🏃","tone":"mint","title":"Present Continuous","big":"is/am/are + Ving","ask":"กำลังทำอยู่ตอนนี้ ใช้รูปไหน","sub":"กำลังทำอยู่ตอนนี้","blocks":[{"k":"list","items":[{"icon":"🔑","t":"คำบอกเวลา: now, at the moment, Look!, Listen!"},{"icon":"🚫","t":"กริยาบอกสภาพไม่ใช้ -ing","d":"know, like, love, want, believe, own: I know him. (ไม่ใช่ I am knowing)"}]}]},{"id":"perfect","icon":"🔗","tone":"sky","title":"Present Perfect","big":"have/has + V3","hot":true,"ask":"since / for / already / yet ใช้กับ tense อะไร","sub":"since · for · already · yet · just · ever","blocks":[{"k":"pairs","items":[{"a":"since + จุดเวลา","b":"since 2020, since Monday"},{"a":"for + ช่วงเวลา","b":"for 3 years, for two weeks"}]},{"k":"example","q":"She ___ here since 2020.","steps":["since + จุดเวลา → Present Perfect","ประธาน She → has + V3"],"a":"has worked"},{"k":"oops","t":"มี yesterday, ago, last year อยู่ในประโยค ห้ามใช้ Present Perfect ต้องใช้ Past Simple"}]},{"id":"past","icon":"⏮️","tone":"lem","title":"Past Simple","big":"V2","must":true,"ask":"yesterday / ago / last ... ใช้ tense อะไร","sub":"yesterday · ago · last week · in 2019","blocks":[{"k":"example","q":"I ___ my old teacher two days ago.","steps":["ago → เหตุการณ์จบแล้วในอดีต","ใช้กริยาช่องที่ 2"],"a":"met"}]},{"id":"pastcont","icon":"📞","tone":"lil","title":"Past Continuous + when","big":"was/were + Ving","ask":"เหตุการณ์ยาวในอดีตถูกขัดจังหวะ ใช้รูปไหน","sub":"เหตุการณ์ยาว ถูกเหตุการณ์สั้นขัดจังหวะ","blocks":[{"k":"example","q":"I was cooking when the phone ___.","steps":["เหตุการณ์ยาว (กำลังทำอาหาร) = was cooking","เหตุการณ์สั้นที่แทรกเข้ามา = Past Simple"],"a":"rang"},{"k":"memo","t":"\"while + ยาว (Ving) · when + สั้น (V2)\""}]},{"id":"future","icon":"🔮","tone":"pea","title":"อนาคต & if / when","big":"if + V1","hot":true,"ask":"ประโยคหลัง if / when ที่พูดถึงอนาคต ใช้ will ได้ไหม","sub":"หลัง if / when ที่พูดถึงอนาคต ใช้ Present ไม่ใช้ will","blocks":[{"k":"pairs","items":[{"a":"will + V1","b":"ตัดสินใจทันที คาดเดา: I''ll help you."},{"a":"be going to + V1","b":"วางแผนไว้แล้ว มีหลักฐาน: It''s going to rain."}]},{"k":"example","q":"I will call you when I ___ home.","steps":["หลัง when (พูดถึงอนาคต) ใช้ Present Simple"],"a":"get (ไม่ใช่ will get)"}]}]}'::jsonb),
  ('a2-grammar', 'A2', false, 17, '{"id":"a2-grammar","group":"A2","topics":["A2-GRAMMAR"],"icon":"🧩","title":"ไวยากรณ์ที่ออกบ่อย","hub":"Grammar","hubSub":"6 เรื่องที่ออกบ่อย","branches":[{"id":"agree","icon":"🤝","tone":"pink","title":"ประธาน-กริยาสอดคล้อง","big":"each → เอกพจน์","hot":true,"ask":"each / every ตามด้วยกริยารูปไหน","sub":"each, every, everyone ใช้กริยาเอกพจน์","blocks":[{"k":"table","head":["รูปแบบ","กริยา"],"rows":[["Each / Every / Everyone","เอกพจน์ (is, has, V-s)"],["The number of + นามพหูพจน์","เอกพจน์"],["A number of + นามพหูพจน์","พหูพจน์"],["Neither A nor B / Either A or B","ตามตัวที่อยู่ใกล้กริยา (B)"]]},{"k":"example","q":"Each of the students ___ a book.","steps":["Each → เอกพจน์ (อย่าดูที่ students)"],"a":"has"}]},{"id":"if","icon":"❓","tone":"mint","title":"If-clause","big":"4","unit":"แบบ","must":true,"ask":"If-clause มีกี่แบบ","blocks":[{"k":"table","head":["แบบ","If ...","ประโยคหลัก"],"rows":[["0 ความจริง","Present","Present"],["1 เป็นไปได้","Present","will + V1"],["2 ไม่จริงตอนนี้","Past (were)","would + V1"],["3 ไม่จริงในอดีต","had + V3","would have + V3"]]},{"k":"example","q":"If I ___ you, I would study harder.","steps":["would + V1 → แบบที่ 2","สมมติไม่จริง ใช้ were กับทุกประธาน"],"a":"were"}]},{"id":"passive","icon":"🔄","tone":"sky","title":"Passive Voice","big":"be + V3","ask":"ประธานถูกกระทำ ใช้รูปไหน","sub":"ประธานเป็นผู้ถูกกระทำ","blocks":[{"k":"example","q":"The report ___ by the teacher yesterday.","steps":["รายงานถูกเขียน (ถูกกระทำ) → be + V3","yesterday → was"],"a":"was written"},{"k":"memo","t":"เจอ by + ผู้กระทำ ให้นึกถึง Passive ก่อน"}]},{"id":"relative","icon":"🔗","tone":"lem","title":"Relative Pronoun","big":"who · which · whose","ask":"ใช้ who กับ which ต่างกันอย่างไร","blocks":[{"k":"table","head":["คำ","ใช้กับ"],"rows":[["who","คน (เป็นประธาน)"],["whom","คน (เป็นกรรม)"],["which","สัตว์ สิ่งของ"],["whose","แสดงความเป็นเจ้าของ + นาม"],["that","ได้ทั้งคน สิ่งของ แต่ใช้หลังจุลภาค (,) ไม่ได้"]]},{"k":"example","q":"The teacher ___ car is red is my friend.","steps":["ตามด้วยคำนาม car และแสดงความเป็นเจ้าของ"],"a":"whose"}]},{"id":"gerund","icon":"🎬","tone":"lil","title":"Ving หรือ to V","big":"enjoy + Ving","hot":true,"ask":"enjoy / avoid / finish / mind ตามด้วยอะไร","blocks":[{"k":"pairs","items":[{"a":"+ Ving","b":"enjoy, avoid, finish, mind, keep, suggest, practise"},{"a":"+ to V","b":"want, decide, plan, hope, agree, promise, refuse"}]},{"k":"pairs","items":[{"a":"stop smoking","b":"เลิกสูบบุหรี่"},{"a":"stop to smoke","b":"หยุด (สิ่งที่ทำอยู่) เพื่อไปสูบบุหรี่"}]},{"k":"memo","t":"\"เอนจอย อะวอยด์ ฟินิช มายด์\" ตามด้วย -ing"}]},{"id":"compare","icon":"📏","tone":"pea","title":"เปรียบเทียบ","big":"as ... as","ask":"เท่ากัน ใช้โครงสร้างอะไร","blocks":[{"k":"table","head":["แบบ","รูป"],"rows":[["เท่ากัน","as + adj + as"],["ขั้นกว่า (สั้น)","adj-er + than"],["ขั้นกว่า (ยาว)","more + adj + than"],["ขั้นสูงสุด","the + adj-est / the most + adj"],["รูปพิเศษ","good → better → best · bad → worse → worst"]]}]}]}'::jsonb),
  ('a2-vocab1', 'A2', true, 18, '{"id":"a2-vocab1","group":"A2","topics":["A2-VOCAB"],"icon":"🧱","free":true,"title":"Vocabulary 1: รากคำ คำคล้าย คำตรงข้าม","hub":"Vocabulary","hubSub":"เดาความหมายจากส่วนประกอบคำ","branches":[{"id":"prefix","icon":"⬅️","tone":"pink","title":"Prefix หน้าคำ","big":"un · dis · mis","must":true,"ask":"prefix ที่แปลว่า \"ไม่ / ตรงข้าม\" มีอะไรบ้าง","sub":"เติมหน้าคำ เปลี่ยนความหมาย","blocks":[{"k":"table","head":["Prefix","ความหมาย","ตัวอย่าง"],"rows":[["un- in- im- il- ir- dis-","ไม่ / ตรงข้าม","unhappy, impossible, illegal, irregular, dislike"],["re-","อีกครั้ง","rewrite, review"],["pre-","ก่อน","preview, prepare"],["mis-","ผิด","misunderstand, mistake"],["over- / under-","มากเกิน / น้อยเกิน","overwork, underpaid"]]}]},{"id":"suffix","icon":"➡️","tone":"mint","title":"Suffix ท้ายคำ","big":"-tion = นาม","hot":true,"ask":"คำลงท้าย -tion, -ment, -ness เป็นคำชนิดไหน","sub":"ท้ายคำบอกชนิดของคำ ช่วยเลือกคำเติมช่องว่าง","blocks":[{"k":"table","head":["ชนิดคำ","ท้ายคำ"],"rows":[["คำนาม","-tion, -ment, -ness, -ity, -ance, -er/-or"],["คุณศัพท์","-ful, -less, -ous, -able, -ive, -al"],["กริยาวิเศษณ์","-ly"],["กริยา","-ize, -en, -ify"]]},{"k":"example","q":"Her ___ to the school is admirable. (dedicate)","steps":["หลัง Her ต้องเป็นคำนาม","dedicate → dedication"],"a":"dedication"}]},{"id":"confuse","icon":"🤯","tone":"sky","title":"คำที่หน้าตาคล้ายกัน","big":"affect / effect","hot":true,"ask":"affect กับ effect ต่างกันอย่างไร","sub":"affect = กริยา · effect = คำนาม","blocks":[{"k":"words","items":[{"w":"affect (v.)","m":"ส่งผลต่อ","ex":"Stress affects learning."},{"w":"effect (n.)","m":"ผลกระทบ","ex":"a positive effect"},{"w":"accept","m":"ยอมรับ"},{"w":"except","m":"ยกเว้น"},{"w":"advice (n.)","m":"คำแนะนำ"},{"w":"advise (v.)","m":"แนะนำ"},{"w":"borrow","m":"ยืม (จากคนอื่น)"},{"w":"lend","m":"ให้ยืม"},{"w":"principal","m":"ครูใหญ่ / หลัก"},{"w":"principle","m":"หลักการ"},{"w":"economic","m":"เกี่ยวกับเศรษฐกิจ"},{"w":"economical","m":"ประหยัด"},{"w":"sensible","m":"มีเหตุผล"},{"w":"sensitive","m":"อ่อนไหว"}]}]},{"id":"syn","icon":"🟰","tone":"lem","title":"คำความหมายเหมือน","big":"big = huge","ask":"\"huge\" ความหมายใกล้กับคำใด","blocks":[{"k":"words","items":[{"w":"huge","m":"= enormous, big"},{"w":"tiny","m":"= small, little"},{"w":"begin","m":"= start, commence"},{"w":"finish","m":"= complete, end"},{"w":"help","m":"= assist, support"},{"w":"show","m":"= display, demonstrate"},{"w":"important","m":"= significant, essential"},{"w":"difficult","m":"= hard, challenging"},{"w":"improve","m":"= enhance, develop"}]}]},{"id":"ant","icon":"↔️","tone":"lil","title":"คำความหมายตรงข้าม","big":"increase ↔ decrease","ask":"คำตรงข้ามของ increase","blocks":[{"k":"words","items":[{"w":"increase","m":"↔ decrease, reduce"},{"w":"ancient","m":"↔ modern"},{"w":"accept","m":"↔ refuse, reject"},{"w":"permanent","m":"↔ temporary"},{"w":"generous","m":"↔ selfish, mean"},{"w":"expensive","m":"↔ cheap"},{"w":"polite","m":"↔ rude"},{"w":"strengthen","m":"↔ weaken"},{"w":"punctual","m":"↔ late"}]}]},{"id":"family","icon":"👪","tone":"pea","title":"ตระกูลคำ","big":"เลือกชนิดคำ","ask":"เติมคำในช่องว่าง ดูอะไรก่อน","sub":"ดูตำแหน่งในประโยค แล้วเลือกรูปคำให้ตรงชนิด","blocks":[{"k":"table","head":["กริยา","นาม","คุณศัพท์","วิเศษณ์"],"rows":[["succeed","success","successful","successfully"],["create","creation / creativity","creative","creatively"],["decide","decision","decisive","decisively"],["educate","education","educational","educationally"]]},{"k":"memo","t":"หลัง a/an/the/his = นาม · หน้าคำนาม = คุณศัพท์ · ขยายกริยา = วิเศษณ์ (-ly)"}]}]}'::jsonb),
  ('a2-vocab2', 'A2', false, 19, '{"id":"a2-vocab2","group":"A2","topics":["A2-VOCAB"],"icon":"🎒","title":"Vocabulary 2: คำศัพท์ครู งาน และวลี","hub":"Vocabulary 2","hubSub":"คำที่เจอในข้อสอบครู","branches":[{"id":"school","icon":"🏫","tone":"pink","title":"คำศัพท์การศึกษา","big":"curriculum","unit":"= หลักสูตร","must":true,"ask":"\"หลักสูตร\" ภาษาอังกฤษคือ","blocks":[{"k":"words","items":[{"w":"curriculum","m":"หลักสูตร"},{"w":"syllabus","m":"เค้าโครงรายวิชา"},{"w":"lesson plan","m":"แผนการสอน"},{"w":"assessment","m":"การประเมิน"},{"w":"evaluation","m":"การประเมินผล"},{"w":"objective","m":"จุดประสงค์"},{"w":"achievement","m":"ผลสัมฤทธิ์"},{"w":"attendance","m":"การเข้าเรียน"},{"w":"enrollment","m":"การลงทะเบียนเรียน"},{"w":"scholarship","m":"ทุนการศึกษา"},{"w":"learner-centered","m":"ผู้เรียนเป็นสำคัญ"},{"w":"principal","m":"ผู้อำนวยการโรงเรียน"}]}]},{"id":"work","icon":"💼","tone":"mint","title":"คำศัพท์งานราชการ","big":"applicant","unit":"= ผู้สมัคร","ask":"\"ผู้สมัคร\" ภาษาอังกฤษคือ","blocks":[{"k":"words","items":[{"w":"applicant","m":"ผู้สมัคร"},{"w":"application form","m":"ใบสมัคร"},{"w":"qualification","m":"คุณสมบัติ วุฒิ"},{"w":"deadline","m":"กำหนดส่ง วันสุดท้าย"},{"w":"appointment","m":"การนัดหมาย การแต่งตั้ง"},{"w":"civil servant","m":"ข้าราชการ"},{"w":"colleague","m":"เพื่อนร่วมงาน"},{"w":"responsibility","m":"ความรับผิดชอบ"},{"w":"regulation","m":"ระเบียบ ข้อบังคับ"}]}]},{"id":"phrasal","icon":"🧷","tone":"sky","title":"Phrasal Verbs","big":"look after","unit":"= ดูแล","hot":true,"ask":"\"look after\" แปลว่า","blocks":[{"k":"words","items":[{"w":"look after","m":"ดูแล"},{"w":"look for","m":"มองหา"},{"w":"look forward to + Ving","m":"ตั้งตารอ"},{"w":"give up","m":"เลิก ยอมแพ้"},{"w":"put off","m":"เลื่อนออกไป"},{"w":"carry out","m":"ดำเนินการ"},{"w":"turn down","m":"ปฏิเสธ / หรี่เสียง"},{"w":"find out","m":"ค้นพบ หาคำตอบ"},{"w":"take part in","m":"เข้าร่วม"},{"w":"get along with","m":"เข้ากันได้ดี"},{"w":"come across","m":"พบโดยบังเอิญ"},{"w":"hand in","m":"ส่ง (งาน)"}]},{"k":"oops","t":"look forward to + Ving เช่น I look forward to hearing from you. (to ในวลีนี้ไม่ใช่ to V)"}]},{"id":"colloc","icon":"🧲","tone":"lem","title":"คำที่ใช้คู่กัน","big":"make a decision","ask":"\"ตัดสินใจ\" ใช้ make หรือ do","blocks":[{"k":"pairs","items":[{"a":"make","b":"a decision, a mistake, progress, an effort, a plan"},{"a":"do","b":"homework, research, your best, a favour, exercise"},{"a":"take","b":"an exam, a break, notes, part in, care of"},{"a":"pay","b":"attention, a visit, a compliment"}]}]},{"id":"linker","icon":"🔗","tone":"lil","title":"คำเชื่อม","big":"despite + นาม","hot":true,"ask":"despite / although อันไหนตามด้วยประโยค","sub":"although + ประโยค · despite / in spite of + คำนาม","blocks":[{"k":"table","head":["ความหมาย","คำเชื่อม"],"rows":[["แม้ว่า","although + ประโยค · despite / in spite of + นาม/Ving"],["แต่ อย่างไรก็ตาม","but, however (ใช้ ; however, หรือขึ้นประโยคใหม่)"],["ดังนั้น","so, therefore, as a result"],["นอกจากนี้","moreover, furthermore, in addition"],["เพราะ","because + ประโยค · because of + นาม"]]},{"k":"example","q":"___ the heavy rain, the students came to school.","steps":["ตามด้วยคำนาม (the heavy rain) ไม่ใช่ประโยค"],"a":"Despite"}]},{"id":"idiom","icon":"🎈","tone":"pea","title":"สำนวนยอดฮิต","big":"piece of cake","unit":"= ง่ายมาก","ask":"\"a piece of cake\" แปลว่า","blocks":[{"k":"words","items":[{"w":"a piece of cake","m":"ง่ายมาก"},{"w":"break the ice","m":"ทำให้บรรยากาศหายเกร็ง"},{"w":"under the weather","m":"ไม่ค่อยสบาย"},{"w":"once in a blue moon","m":"นาน ๆ ครั้ง"},{"w":"hit the books","m":"ตั้งใจอ่านหนังสือ"},{"w":"on cloud nine","m":"มีความสุขมาก"}]}]}]}'::jsonb),
  ('a2-conv', 'A2', false, 20, '{"id":"a2-conv","group":"A2","topics":["A2-CONV"],"icon":"💬","title":"บทสนทนา (Conversation)","hub":"Conversation","hubSub":"เลือกคำตอบให้เข้ากับสถานการณ์","branches":[{"id":"greet","icon":"👋","tone":"pink","title":"ทักทาย","big":"How do you do?","unit":"→ How do you do?","must":true,"ask":"ตอบ \"How do you do?\" อย่างไร","sub":"พบกันครั้งแรก ตอบด้วยประโยคเดิม","blocks":[{"k":"table","head":["พูดว่า","ตอบว่า"],"rows":[["How do you do?","How do you do."],["How are you?","Fine, thank you. And you?"],["Nice to meet you.","Nice to meet you, too."],["What do you do?","I''m a teacher. (ถามอาชีพ)"]]},{"k":"oops","t":"What do you do? ถามอาชีพ ไม่ได้ถามว่ากำลังทำอะไรอยู่"}]},{"id":"thanks","icon":"🙏","tone":"mint","title":"ขอบคุณ / ขอโทษ","big":"You''re welcome.","ask":"ตอบ \"Thank you\" อย่างไร","blocks":[{"k":"pairs","items":[{"a":"Thank you.","b":"You''re welcome. / My pleasure. / Not at all."},{"a":"I''m sorry.","b":"That''s all right. / Never mind. / No problem."}]}]},{"id":"mind","icon":"🙋","tone":"sky","title":"Would you mind ...?","big":"No = ยินดี","hot":true,"ask":"ตอบ \"Would you mind ...?\" ว่า No แปลว่าอะไร","sub":"ตอบ No, not at all. = ไม่รังเกียจ ยินดีช่วย","blocks":[{"k":"pairs","items":[{"a":"Would you mind opening the window?","b":"No, not at all. / Of course not. = ได้เลย"},{"a":"Could you / Can I ...?","b":"Sure. / Go ahead. / Certainly."}]},{"k":"oops","t":"ตอบ Would you mind ...? ด้วย Yes แปลว่ารังเกียจ ไม่ยอมทำ ข้อสอบชอบหลอกตรงนี้"}]},{"id":"offer","icon":"🎁","tone":"lem","title":"เสนอ / ชวน","big":"I''d love to.","ask":"ตอบรับคำชวนอย่างสุภาพว่าอย่างไร","blocks":[{"k":"table","head":["พูดว่า","ตอบรับ","ปฏิเสธ"],"rows":[["Would you like some tea?","Yes, please.","No, thank you."],["Would you like to join us?","I''d love to.","I''m afraid I can''t."],["Shall we go now?","Sure, let''s go.","Let''s wait a bit."]]}]},{"id":"opinion","icon":"💭","tone":"lil","title":"เห็นด้วย / ไม่เห็นด้วย","big":"I couldn''t agree more.","ask":"\"I couldn''t agree more\" แปลว่าอะไร","sub":"= เห็นด้วยอย่างยิ่ง","blocks":[{"k":"pairs","items":[{"a":"เห็นด้วย","b":"I couldn''t agree more. / Absolutely. / That''s true."},{"a":"ไม่เห็นด้วย (สุภาพ)","b":"I''m not sure about that. / I see your point, but ..."}]},{"k":"oops","t":"I couldn''t agree more มีคำว่า couldn''t แต่แปลว่า \"เห็นด้วยที่สุด\""}]},{"id":"phone","icon":"☎️","tone":"pea","title":"โทรศัพท์ / ถามทาง","big":"Hold on, please.","ask":"\"กรุณารอสักครู่\" ทางโทรศัพท์พูดว่าอย่างไร","blocks":[{"k":"words","items":[{"w":"Hold on, please.","m":"กรุณารอสักครู่"},{"w":"Who''s calling, please?","m":"ใครพูดสายคะ/ครับ"},{"w":"May I take a message?","m":"ฝากข้อความไหม"},{"w":"Go straight on.","m":"ตรงไป"},{"w":"Turn left / right.","m":"เลี้ยวซ้าย / ขวา"},{"w":"It''s opposite the bank.","m":"อยู่ตรงข้ามธนาคาร"}]}]}]}'::jsonb),
  ('a2-read', 'A2', false, 21, '{"id":"a2-read","group":"A2","topics":["A2-READING"],"icon":"📰","title":"การอ่าน (Reading)","hub":"Reading","hubSub":"อ่านคำถามก่อนอ่านเรื่อง","intro":"อ่านคำถามก่อน แล้วค่อยกลับไปหาคำตอบในบทความ ประหยัดเวลามาก","branches":[{"id":"main","icon":"🎯","tone":"pink","title":"Main idea / Title","big":"คลุมทั้งเรื่อง","must":true,"ask":"ตัวเลือกที่เป็น main idea ต้องมีลักษณะอย่างไร","sub":"ไม่แคบเกิน (แค่รายละเอียด) ไม่กว้างเกิน","blocks":[{"k":"list","items":[{"icon":"🔍","t":"ดูประโยคแรกของแต่ละย่อหน้า และย่อหน้าสุดท้าย"},{"icon":"❌","t":"ตัดตัวเลือกที่พูดถึงแค่ย่อหน้าเดียว (แคบเกิน)"},{"icon":"❌","t":"ตัดตัวเลือกที่กว้างกว่าเรื่องที่อ่าน"}]}]},{"id":"scan","icon":"🔦","tone":"mint","title":"Skim vs Scan","big":"Scan = หาเจาะจง","ask":"หาตัวเลข ชื่อ วันที่ ในบทความ ใช้วิธีไหน","blocks":[{"k":"pairs","items":[{"a":"Skimming","b":"อ่านผ่านเร็ว ๆ เพื่อจับภาพรวม ใช้กับ main idea"},{"a":"Scanning","b":"กวาดตาหาคำเจาะจง ตัวเลข ชื่อ วันที่ ใช้กับคำถามรายละเอียด"}]}]},{"id":"refer","icon":"👉","tone":"sky","title":"คำอ้างถึง (it, they, this)","big":"ย้อนไปข้างหน้า","hot":true,"ask":"\"it\" ในบทความ อ้างถึงคำที่อยู่ตรงไหน","sub":"หาคำนามที่อยู่ก่อนหน้า และพจน์ตรงกัน","blocks":[{"k":"list","items":[{"icon":"1️⃣","t":"it / this = เอกพจน์ · they / these = พหูพจน์"},{"icon":"2️⃣","t":"ย้อนไปหาคำนามที่อยู่ใกล้ที่สุดก่อนหน้า"},{"icon":"3️⃣","t":"แทนคำนั้นลงในประโยค ถ้าความหมายลงตัว คือคำตอบ"}]}]},{"id":"context","icon":"🧩","tone":"lem","title":"เดาศัพท์จากบริบท","big":"ดูคำรอบ ๆ","ask":"เจอคำศัพท์ไม่รู้จัก ทำอย่างไร","blocks":[{"k":"list","items":[{"icon":"🔗","t":"คำอธิบายตามหลัง: that is, or, which means"},{"icon":"↔️","t":"คำบอกความขัดแย้ง: but, however, unlike → ความหมายตรงข้าม"},{"icon":"🧱","t":"แยกรากคำ prefix / suffix (ดูแผนผัง Vocabulary 1)"}]}]},{"id":"infer","icon":"🕵️","tone":"lil","title":"อนุมาน (infer / imply)","big":"ไม่ได้เขียนตรง ๆ","hot":true,"ask":"คำถาม infer / imply ต้องการคำตอบแบบไหน","sub":"แต่ต้องมีหลักฐานในบทความรองรับ","blocks":[{"k":"oops","t":"ตัวเลือกที่ \"จริงในชีวิตจริง\" แต่บทความไม่ได้บอก ไม่ใช่คำตอบ ต้องอ้างจากเนื้อเรื่องเท่านั้น"}]},{"id":"tf","icon":"✅","tone":"pea","title":"จริง / ไม่จริง / ไม่ได้กล่าวถึง","big":"Not mentioned","ask":"ข้อมูลที่บทความไม่ได้พูดถึง ตอบว่าอะไร","blocks":[{"k":"list","items":[{"icon":"⚠️","t":"ระวังคำเด็ดขาด all, always, never ในตัวเลือก มักผิด"},{"icon":"🔎","t":"ตัวเลือกที่ถอดความ (paraphrase) จากบทความ มักเป็นคำตอบที่ถูก"}]}]}]}'::jsonb)
